import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import type { PipelineRunRequest } from "@/api/types";
import { Search, Loader2, ChevronDown, ChevronRight } from "lucide-react";

/**
 * Validation constants matching backend api/schemas.py PipelineRunRequest exactly.
 * HB-01: Client-side validation MUST match API validation exactly.
 */
const VALIDATION = {
  domain: { maxLength: 200, default: "AI/NLP" },
  max_gaps: { min: 1, max: 20, default: 5 },
  generation_rounds: { min: 1, max: 10, default: 2 },
  ideas_per_round: { min: 1, max: 20, default: 5 },
  export_formats: ["markdown", "latex"] as const,
} as const;

export { VALIDATION };

interface RunConfigFormProps {
  onSubmit: (config: PipelineRunRequest) => void;
  isLoading?: boolean;
  sessionId?: string;
  onSessionIdChange?: (value: string) => void;
  initialDomain?: string;
}

export function RunConfigForm({ onSubmit, isLoading, sessionId = "", onSessionIdChange, initialDomain = "" }: RunConfigFormProps) {
  const [domain, setDomain] = useState(initialDomain);
  const [maxGaps, setMaxGaps] = useState(VALIDATION.max_gaps.default);
  const [ideasPerRound, setIdeasPerRound] = useState(VALIDATION.ideas_per_round.default);
  const [generationRounds, setGenerationRounds] = useState(VALIDATION.generation_rounds.default);
  const [exportFormat, setExportFormat] = useState<string>(VALIDATION.export_formats[0]);
  const [runNovelty, setRunNovelty] = useState(true);
  const [runFeasibility, setRunFeasibility] = useState(true);
  const [runSynthesis, setRunSynthesis] = useState(true);
  const [searchQueries, setSearchQueries] = useState("");
  const [advancedOpen, setAdvancedOpen] = useState(false);
  const [strategy, setStrategy] = useState<string>("deep_research");

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!domain.trim()) {
      const confirmed = window.confirm(
        "No research domain specified. The pipeline will use 'AI/NLP' as default. Continue?"
      );
      if (!confirmed) return;
    }
    const config: PipelineRunRequest = {
      domain: domain || undefined,
      max_gaps: maxGaps,
      generation_rounds: generationRounds,
      ideas_per_round: ideasPerRound,
      search_queries: searchQueries
        ? searchQueries.split(",").map((q) => q.trim()).filter(Boolean)
        : undefined,
      run_novelty: runNovelty,
      run_feasibility: runFeasibility,
      run_synthesis: runSynthesis,
      export_format: exportFormat,
      strategy,
    };
    onSubmit(config);
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-lg">Pipeline Configuration</CardTitle>
      </CardHeader>
      <CardContent>
        <form onSubmit={handleSubmit} className="space-y-4">
          {/* Domain */}
          <div className="space-y-2">
            <label className="text-sm font-medium">Research Domain</label>
            <Input
              placeholder="e.g., machine learning, nlp, computer vision"
              value={domain}
              onChange={(e) => setDomain(e.target.value)}
              maxLength={VALIDATION.domain.maxLength}
            />
          </div>

          {/* Strategy Selection */}
          <div className="space-y-2">
            <label className="text-sm font-medium">Pipeline Strategy</label>
            <select
              value={strategy}
              onChange={(e) => setStrategy(e.target.value)}
              className="w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              data-testid="strategy-select"
            >
              <option value="fast_scan">Quick Scan (~2-5 min)</option>
              <option value="deep_research">Deep Research (~25 min)</option>
              <option value="academic_proposal">Academic Proposal (~45 min)</option>
              <option value="literature_review">Literature Review (~10 min)</option>
            </select>
            <p className="text-xs text-muted-foreground">
              {strategy === "fast_scan" && "Fast scan skips tree search and metrics for rapid results."}
              {strategy === "deep_research" && "Full pipeline with tree search, novelty checking, and proposal synthesis."}
              {strategy === "academic_proposal" && "Stricter thresholds and longer timeouts for academic-grade proposals."}
              {strategy === "literature_review" && "Literature search and gap analysis only, no proposal generation."}
            </p>
          </div>

          {/* Core numeric fields */}
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <label className="text-sm font-medium" htmlFor="max-gaps-input">Max Gaps</label>
              <Input
                id="max-gaps-input"
                type="number"
                min={VALIDATION.max_gaps.min}
                max={VALIDATION.max_gaps.max}
                value={maxGaps}
                onChange={(e) => setMaxGaps(Number(e.target.value))}
                data-testid="max-gaps-input"
                aria-label="Maximum research gaps to find"
              />
            </div>
            <div className="space-y-2">
              <label className="text-sm font-medium" htmlFor="ideas-per-round-input">Ideas Per Round</label>
              <Input
                id="ideas-per-round-input"
                type="number"
                min={VALIDATION.ideas_per_round.min}
                max={VALIDATION.ideas_per_round.max}
                value={ideasPerRound}
                onChange={(e) => setIdeasPerRound(Number(e.target.value))}
                aria-label="Number of ideas to generate per round"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <label className="text-sm font-medium" htmlFor="generation-rounds-input">Generation Rounds</label>
              <Input
                id="generation-rounds-input"
                type="number"
                min={VALIDATION.generation_rounds.min}
                max={VALIDATION.generation_rounds.max}
                value={generationRounds}
                onChange={(e) => setGenerationRounds(Number(e.target.value))}
                data-testid="generation-rounds-input"
                aria-label="Number of generation rounds"
              />
            </div>
            <div className="space-y-2">
              <label className="text-sm font-medium">Export Format</label>
              <select
                value={exportFormat}
                onChange={(e) => setExportFormat(e.target.value)}
                data-testid="export-format-select"
                className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
              >
                {VALIDATION.export_formats.map((fmt) => (
                  <option key={fmt} value={fmt}>
                    {fmt.charAt(0).toUpperCase() + fmt.slice(1)}
                  </option>
                ))}
              </select>
            </div>
          </div>

          {/* Search Queries */}
          <div className="space-y-2">
            <label className="text-sm font-medium">Search Queries (comma-separated)</label>
            <Input
              placeholder="transformer attention, few-shot learning"
              value={searchQueries}
              onChange={(e) => setSearchQueries(e.target.value)}
            />
          </div>

          {/* Advanced Options - Collapsible */}
          <div className="border rounded-md">
            <button
              type="button"
              onClick={() => setAdvancedOpen(!advancedOpen)}
              className="flex items-center gap-2 w-full px-4 py-3 text-sm font-medium text-left hover:bg-muted/50 transition-colors"
              data-testid="advanced-toggle"
              aria-expanded={advancedOpen}
            >
              {advancedOpen ? (
                <ChevronDown className="h-4 w-4" />
              ) : (
                <ChevronRight className="h-4 w-4" />
              )}
              Advanced Options
            </button>
            {advancedOpen && (
              <div className="px-4 pb-4 space-y-3" data-testid="advanced-content">
                {/* Session ID (moved from top-level — P1-03) */}
                <div className="space-y-2">
                  <label className="text-sm font-medium" htmlFor="session-id-input">
                    Session ID (optional)
                  </label>
                  <input
                    id="session-id-input"
                    type="text"
                    placeholder="e.g., my-session-name"
                    value={sessionId}
                    onChange={(e) => onSessionIdChange?.(e.target.value)}
                    data-testid="session-id-input"
                    className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                    maxLength={200}
                  />
                  <p className="text-xs text-muted-foreground">
                    Group multiple runs under the same session for easy tracking.
                  </p>
                </div>

                {/* Run Toggles */}
                <div className="flex items-center justify-between">
                  <label className="text-sm font-medium" htmlFor="run-novelty-toggle">
                    Run Novelty Check
                  </label>
                  <input
                    id="run-novelty-toggle"
                    type="checkbox"
                    checked={runNovelty}
                    onChange={(e) => setRunNovelty(e.target.checked)}
                    data-testid="run-novelty-toggle"
                    className="h-4 w-4 rounded border-input"
                  />
                </div>
                <div className="flex items-center justify-between">
                  <label className="text-sm font-medium" htmlFor="run-feasibility-toggle">
                    Run Feasibility Scoring
                  </label>
                  <input
                    id="run-feasibility-toggle"
                    type="checkbox"
                    checked={runFeasibility}
                    onChange={(e) => setRunFeasibility(e.target.checked)}
                    data-testid="run-feasibility-toggle"
                    className="h-4 w-4 rounded border-input"
                  />
                </div>
                <div className="flex items-center justify-between">
                  <label className="text-sm font-medium" htmlFor="run-synthesis-toggle">
                    Run Proposal Synthesis
                  </label>
                  <input
                    id="run-synthesis-toggle"
                    type="checkbox"
                    checked={runSynthesis}
                    onChange={(e) => setRunSynthesis(e.target.checked)}
                    data-testid="run-synthesis-toggle"
                    className="h-4 w-4 rounded border-input"
                  />
                </div>
              </div>
            )}
          </div>

          <Button type="submit" disabled={isLoading} className="w-full">
            {isLoading ? (
              <Loader2 className="mr-2 h-4 w-4 animate-spin" />
            ) : (
              <Search className="mr-2 h-4 w-4" />
            )}
            {isLoading ? "Starting..." : "Start Pipeline"}
          </Button>
        </form>
      </CardContent>
    </Card>
  );
}

import { apiFetch } from "./client";
import type {
  PipelineRunRequest,
  PipelineRunSummary,
  PipelineRunDetail,
  TriggerRunResponse,
  AutonomousCycleRequest,
  AutonomousCycleResponse,
  IdeaSummary,
} from "./types";

export function triggerRun(req: PipelineRunRequest): Promise<TriggerRunResponse> {
  return apiFetch("/pipeline/run", {
    method: "POST",
    body: JSON.stringify(req),
  });
}

export function listRuns(params?: {
  limit?: number;
  offset?: number;
  session_id?: string;
}): Promise<{ runs: PipelineRunSummary[]; total: number }> {
  const search = new URLSearchParams();
  if (params?.limit) search.set("limit", String(params.limit));
  if (params?.offset) search.set("offset", String(params.offset));
  if (params?.session_id) search.set("session_id", params.session_id);
  const qs = search.toString();
  return apiFetch(`/pipeline/runs${qs ? `?${qs}` : ""}`);
}

export function getRunDetail(id: number): Promise<PipelineRunDetail> {
  return apiFetch(`/pipeline/runs/detail/${id}`);
}

export function cancelRun(runId: string): Promise<{ status: string; run_id: string }> {
  return apiFetch(`/pipeline/runs/${runId}`, { method: "DELETE" });
}

export function getRunIdeas(runId: number): Promise<{ ideas: IdeaSummary[]; total: number }> {
  return apiFetch(`/pipeline/runs/${runId}/ideas`);
}

export function triggerAutonomous(req: AutonomousCycleRequest): Promise<AutonomousCycleResponse> {
  return apiFetch("/pipeline/autonomous", {
    method: "POST",
    body: JSON.stringify(req),
  });
}

import { useMemo, useState, useEffect, useCallback } from "react";
import { useQuery } from "@tanstack/react-query";
import { useNavigate, useParams } from "react-router-dom";
import { getRunDetail, getRunIdeas } from "@/api/pipeline";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { PIPELINE_STAGES } from "@/lib/constants";
import { cn } from "@/lib/utils";
import {
  ArrowLeft,
  CheckCircle2,
  Circle,
  Loader2,
  AlertTriangle,
  Play,
  Lightbulb,
  Clock,
  GitBranch,
  Timer,
} from "lucide-react";
import type { IdeaSummary } from "@/api/types";
import { TreeVisualization } from "@/components/pipeline/tree-visualization";

const statusColors: Record<string, string> = {
  pending: "bg-yellow-100 text-yellow-800",
  running: "bg-blue-100 text-blue-800",
  completed: "bg-green-100 text-green-800",
  failed: "bg-red-100 text-red-800",
};

function fmtDuration(sec: number): string {
  if (sec < 60) return `${sec.toFixed(0)}s`;
  const m = Math.floor(sec / 60);
  const s = Math.floor(sec % 60);
  if (m < 60) return `${m}m ${s}s`;
  const h = Math.floor(m / 60);
  return `${h}h ${m % 60}m ${s}s`;
}

export default function RunDetail() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const runId = Number(id);

  // Tick every second for live elapsed timer
  const [tick, setTick] = useState(0);

  const {
    data: run,
    isLoading: runLoading,
    error: runError,
  } = useQuery({
    queryKey: ["run", runId],
    queryFn: () => getRunDetail(runId),
    enabled: !isNaN(runId),
    // Fast refetch while running — every 3 seconds
    refetchInterval: (query) => {
      const data = query.state.data;
      return data && data.status === "running" ? 3000 : false;
    },
  });

  const isRunning = run?.status === "running";

  const { data: ideasData } = useQuery({
    queryKey: ["run", runId, "ideas"],
    queryFn: () => getRunIdeas(runId),
    enabled: !isNaN(runId) && !!run,
    refetchInterval: isRunning ? 5000 : false,
  });

  // Live 1-second tick
  useEffect(() => {
    if (!isRunning) return;
    const interval = setInterval(() => setTick((t) => t + 1), 1000);
    return () => clearInterval(interval);
  }, [isRunning]);

  // Live elapsed time
  const elapsedSec = useMemo(() => {
    if (!run) return 0;
    const start = new Date(run.created_at).getTime();
    const end = run.completed_at ? new Date(run.completed_at).getTime() : Date.now();
    return Math.max(0, (end - start) / 1000);
  }, [run, tick]);

  // Stale run detector (BATCH-55)
  const isStale = useMemo(() => {
    if (!run || run.status !== "running") return false;
    const created = new Date(run.created_at).getTime();
    return Date.now() - created > 5 * 60 * 1000;
  }, [run, tick]);

  if (runError) {
    return (
      <div className="space-y-6">
        <Button variant="ghost" onClick={() => navigate("/")} data-testid="back-btn">
          <ArrowLeft className="h-4 w-4 mr-2" />
          Back to Dashboard
        </Button>
        <Card>
          <CardContent className="p-8 text-center" data-testid="run-not-found">
            <AlertTriangle className="h-8 w-8 mx-auto mb-2 text-destructive" />
            <p className="text-lg font-medium">Run not found</p>
            <p className="text-sm text-muted-foreground mt-1">
              No pipeline run found with ID {id}.
            </p>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (runLoading) {
    return (
      <div className="space-y-6">
        <Skeleton className="h-8 w-48" />
        <Skeleton className="h-64 w-full" />
      </div>
    );
  }

  if (!run) {
    return (
      <div className="space-y-6">
        <Button variant="ghost" onClick={() => navigate("/")} data-testid="back-btn">
          <ArrowLeft className="h-4 w-4 mr-2" />
          Back to Dashboard
        </Button>
        <Card>
          <CardContent className="p-8 text-center" data-testid="run-not-found">
            <AlertTriangle className="h-8 w-8 mx-auto mb-2 text-destructive" />
            <p className="text-lg font-medium">Run not found</p>
          </CardContent>
        </Card>
      </div>
    );
  }

  const ideas = ideasData?.ideas ?? [];
  const progressPct = Math.min(100, (run.stages_completed.length / PIPELINE_STAGES.length) * 100);
  const currentStageLabel = PIPELINE_STAGES.find((s) => s.key === run.current_stage)?.label ?? run.current_stage;

  return (
    <div className="space-y-6" data-testid="run-detail">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <Button variant="ghost" onClick={() => navigate("/")} data-testid="back-btn">
            <ArrowLeft className="h-4 w-4 mr-2" />
            Back
          </Button>
          <div>
            <h1 className="text-2xl font-bold tracking-tight" data-testid="run-title">
              Run #{run.id}
            </h1>
            <p className="text-sm text-muted-foreground">{run.domain}</p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          {isRunning && (
            <span className="text-sm text-muted-foreground font-mono tabular-nums flex items-center gap-1">
              <Timer className="h-4 w-4" />
              {fmtDuration(elapsedSec)}
            </span>
          )}
          <Badge className={cn("text-sm", statusColors[run.status])} data-testid="run-status">
            {run.status}
          </Badge>
        </div>
      </div>

      {/* Live Progress Banner */}
      {isRunning && (
        <Card className="border-blue-200 dark:border-blue-800 bg-blue-50/50 dark:bg-blue-900/10" data-testid="live-progress">
          <CardContent className="p-4">
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center gap-2 text-blue-700 dark:text-blue-300">
                <Loader2 className="h-5 w-5 animate-spin" />
                <span className="text-sm font-medium">{currentStageLabel}</span>
              </div>
              <span className="text-xs text-muted-foreground">
                Stage {run.stages_completed.length + 1} of {PIPELINE_STAGES.length}
              </span>
            </div>
            <div className="w-full bg-blue-100 dark:bg-blue-900/30 rounded-full h-2 overflow-hidden">
              <div
                className="h-full bg-blue-500 rounded-full transition-all duration-1000 ease-linear"
                style={{ width: `${progressPct}%` }}
              />
            </div>
          </CardContent>
        </Card>
      )}

      {/* Stale Run Warning (BATCH-55) */}
      {isStale && (
        <div className="bg-yellow-50 dark:bg-yellow-900/20 border border-yellow-200 dark:border-yellow-800 rounded-lg p-4 mb-4" data-testid="stale-run-warning">
          <div className="flex items-center gap-2 text-yellow-800 dark:text-yellow-200">
            <AlertTriangle className="h-5 w-5" />
            <p className="text-sm">
              This run has been running for over 5 minutes. It may have encountered an issue.
              You can try refreshing or starting a new run.
            </p>
          </div>
        </div>
      )}

      {/* Metadata */}
      <Card data-testid="run-metadata">
        <CardHeader>
          <CardTitle className="text-sm font-medium">Run Metadata</CardTitle>
        </CardHeader>
        <CardContent>
          <dl className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
            <div>
              <dt className="text-muted-foreground">ID</dt>
              <dd className="font-medium">{run.id}</dd>
            </div>
            <div>
              <dt className="text-muted-foreground">Domain</dt>
              <dd className="font-medium">{run.domain}</dd>
            </div>
            <div>
              <dt className="text-muted-foreground">Strategy</dt>
              <dd className="font-medium capitalize" data-testid="run-strategy">
                {run.strategy ? run.strategy.replace(/_/g, " ") : "deep research"}
              </dd>
            </div>
            <div>
              <dt className="text-muted-foreground">Created</dt>
              <dd className="font-medium" data-testid="run-created-at">
                {new Date(run.created_at).toLocaleString()}
              </dd>
            </div>
            <div>
              <dt className="text-muted-foreground">Completed</dt>
              <dd className="font-medium" data-testid="run-completed-at">
                {run.completed_at
                  ? new Date(run.completed_at).toLocaleString()
                  : "\u2014"}
              </dd>
            </div>
            <div>
              <dt className="text-muted-foreground">Duration</dt>
              <dd className="font-medium font-mono tabular-nums" data-testid="run-duration">
                {fmtDuration(elapsedSec)}
              </dd>
            </div>
          </dl>
        </CardContent>
      </Card>

      {/* Stages Timeline */}
      <Card data-testid="stages-timeline">
        <CardHeader>
          <CardTitle className="text-sm font-medium">Stages</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-3">
            {PIPELINE_STAGES.map((stage) => {
              const isCompleted = run.stages_completed.includes(stage.key);
              const isCurrent = run.current_stage === stage.key;
              return (
                <div key={stage.key} className="flex items-center gap-3">
                  {isCompleted ? (
                    <CheckCircle2 className="h-5 w-5 text-green-600 flex-shrink-0" />
                  ) : isCurrent ? (
                    <Loader2 className="h-5 w-5 text-blue-600 animate-spin flex-shrink-0" />
                  ) : (
                    <Circle className="h-5 w-5 text-muted-foreground flex-shrink-0" />
                  )}
                  <span
                    className={cn(
                      "text-sm",
                      isCompleted
                        ? "text-foreground font-medium"
                        : isCurrent
                          ? "text-blue-700 font-medium"
                          : "text-muted-foreground",
                    )}
                  >
                    {stage.label}
                  </span>
                  {isCurrent && (
                    <span className="text-xs text-blue-500 ml-auto font-mono">
                      {fmtDuration(elapsedSec)}
                    </span>
                  )}
                </div>
              );
            })}
          </div>
        </CardContent>
      </Card>

      {/* Error Message (for failed runs) */}
      {run.status === "failed" && run.error_message && (
        <Card className="border-destructive" data-testid="error-message">
          <CardContent className="p-4">
            <div className="flex items-start gap-3">
              <AlertTriangle className="h-5 w-5 text-destructive flex-shrink-0 mt-0.5" />
              <div>
                <p className="text-sm font-medium text-destructive">Pipeline Failed</p>
                <p className="text-sm text-muted-foreground mt-1">{run.error_message}</p>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Resume Button (for failed runs) */}
      {run.status === "failed" && (
        <Button data-testid="resume-btn" className="w-full sm:w-auto">
          <Play className="h-4 w-4 mr-2" />
          Resume Pipeline
        </Button>
      )}

      {/* Tree Search Visualization (BATCH-63/TASK-02, AC-02-02) */}
      {run.tree_data && (
        <Card data-testid="tree-search-tab">
          <CardHeader>
            <div className="flex items-center justify-between">
              <CardTitle className="text-sm font-medium">Tree Search</CardTitle>
              <span className="text-sm text-muted-foreground flex items-center gap-1">
                <GitBranch className="h-4 w-4" />
                {run.tree_data.nodes.length} node{run.tree_data.nodes.length !== 1 ? "s" : ""}
              </span>
            </div>
          </CardHeader>
          <CardContent>
            <TreeVisualization tree_data={run.tree_data} />
          </CardContent>
        </Card>
      )}

      {/* Generated Ideas */}
      <Card data-testid="ideas-list">
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle className="text-sm font-medium">Generated Ideas</CardTitle>
            {ideas.length > 0 && (
              <span className="text-sm text-muted-foreground flex items-center gap-1">
                <Lightbulb className="h-4 w-4" />
